import {createHash} from 'node:crypto';
import type {Question} from './assessment';
import {findSubtopic,SUBTOPICS,type Subtopic} from './curriculum';
import corpus from './ela-corpus-v3.json';

/** Finite authored content. A seed selects a plan; it cannot manufacture freshness. */
export const ELA_QUALITY_VERSION='ela-authored-v3.1';
export const ELA_SOURCE_REFERENCES=[
  'https://www.nysed.gov/standards-instruction/english-language-arts',
  'https://www.nysed.gov/sites/default/files/programs/standards-instruction/nys-next-generation-ela-standards.pdf',
  'https://www.schools.nyc.gov/learning/testing/specialized-high-school-admissions-test',
] as const;
type Choice={text:string;reason:string};
type Plan={id:string;target:string;level:number;prompt:string;choices:[Choice,Choice,Choice,Choice];evidence:string;interpretation:string;steps:string[];trap:string;structure:string};
type Passage={id:string;title:string;genre:string;content:string;scenario:string;structure:string;plans:Plan[];sources?:string[]};
type RawPlan={id:string;target:string;prompt:string;choices:[string,string,string,string];reasons:[string,string,string,string];evidence:string;why:string;method:string;trap:string};
type RawPassage=Omit<Passage,'plans'>&{difficulty:number;plans:RawPlan[]};
type Draft={family:string;structure:string;text:string;choices:[string,string,string,string];reasons:[string,string,string,string];rule:string;steps:string[];trap:string};
type FeedbackMetadata={domain:string;topic:string;subtopic:string;familyId:string;scenarioId:string;structureId:string;reasoningType:string;misconception:string;reasoningSteps:number;solutionSteps:string[];howToThink:string;evidenceExplanation:string;qualityVersion:string;contentSignature:string;calibration:{basis:string;status:'editorial';version:string}};
export type ELAQuestionV3=Question&FeedbackMetadata;
const documents=(corpus.passages as unknown as RawPassage[]).map(doc=>({...doc,plans:doc.plans.map(p=>({
  id:p.id,target:p.target,level:doc.difficulty,prompt:p.prompt,choices:p.choices.map((text,i)=>({text,reason:p.reasons[i]})) as Plan['choices'],
  evidence:p.evidence,interpretation:p.why,steps:[p.method,'Compare all four choices with the text; reject unsupported additions or contradictions.',p.why],
  trap:p.trap,structure:`${doc.structure}:${p.target.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`,
}))}));
const hash=(value:string)=>createHash('sha256').update(value).digest('hex');
const slug=(value:string)=>value.toLowerCase().replace(/['’]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
function target(value:string,kind:'reading'|'editing'):Subtopic{
  const found=findSubtopic(value);
  if(!found||found.kind!==kind)throw new Error(`Unsupported ELA ${kind} subtopic: ${value}`);
  return found;
}
function level(difficulty:number){if(!Number.isInteger(difficulty)||difficulty<1||difficulty>5)throw new Error('ELA difficulty must be an integer from 1 to 5.');}
function unavailable(message:string):never{throw Object.assign(new Error(message),{code:'ELA_LIBRARY_EXHAUSTED',status:503});}
function seedNumber(seed:number){if(!Number.isFinite(seed))throw new Error('A finite ELA seed is required.');return Math.abs(Math.trunc(seed));}
function ordered<T>(values:readonly T[],seed:number){const shift=seedNumber(seed)%values.length;return values.slice(shift).concat(values.slice(0,shift));}
function contentSignature(text:string,choices:readonly string[],passage?:string){return hash([passage||'',text,choices.slice().sort().join('|')].join('|').toLowerCase().replace(/\s+/g,' ').trim());}

// Each case is planned around a specific rule and a specific erroneous inference.
// The displayed text is secondary to that rule, key, and distractor rationale.
const draft=(family:string,structure:string,text:string,choices:Draft['choices'],reasons:Draft['reasons'],rule:string,steps:string[],trap:string):Draft=>({family,structure,text,choices,reasons,rule,steps,trap});
const contexts=[
  {name:'Lena',other:'Omar',item:'field guide',plural:'field guides',task:'bird survey'},
  {name:'Amir',other:'Jo',item:'sketch',plural:'sketches',task:'mural project'},
  {name:'Nia',other:'Evan',item:'report',plural:'reports',task:'water study'},
  {name:'Theo',other:'Ruth',item:'photograph',plural:'photographs',task:'archive exhibit'},
  {name:'Iris',other:'Sam',item:'model',plural:'models',task:'design workshop'},
  {name:'Mateo',other:'Ari',item:'recording',plural:'recordings',task:'oral-history project'},
] as const;
const applicationContexts=[
  {name:'Priya',other:'Dante',item:'route notice',plural:'route notices',task:'bus-stop information project'},
  {name:'Ellis',other:'Mina',item:'interview transcript',plural:'interview transcripts',task:'community radio program'},
  {name:'Jules',other:'Asha',item:'costume pattern',plural:'costume patterns',task:'theater production'},
  {name:'Leila',other:'Ben',item:'instrument case',plural:'instrument cases',task:'orchestra storage project'},
  {name:'Soren',other:'Ana',item:'recipe card',plural:'recipe cards',task:'family cookbook'},
  {name:'Maya',other:'Cal',item:'trail sign',plural:'trail signs',task:'park access study'},
] as const;
type EditingContext={name:string;other:string;item:string;plural:string;task:string};
type Builder=(d:number,c:EditingContext)=>Draft;

const agreement:Builder=(d,c)=>{
  const cases=[
    [`The ${c.item} _____ on the shelf.`,['belongs','belong','belonging','to belong'],'The singular subject needs the finite singular verb “belongs.”','simple subject','Do not substitute a participle for the main verb.'],
    [`Each of the ${c.plural} _____ a label.`,['has','have','having','were'],'“Each” is singular; the object of “of” does not control agreement.','intervening phrase','The nearest noun is not necessarily the subject.'],
    [`Neither the editor nor the two assistants _____ available today.`,['are','is','being','was'],'With “neither…nor,” the nearer subject “assistants” is plural.','coordinated subjects','Do not let the first, singular subject control this coordinated construction.'],
    [`Beside the ${c.plural} _____ a ${c.item} that ${c.name} forgot to label.`,['lies','lie','lying','have lain'],'The subject after the verb is singular “a '+c.item+'.”','inverted clause','The introductory prepositional phrase is not the subject.'],
    [`The collection of ${c.plural}, including the ones that ${c.other} restored, _____ the only surviving record of the ${c.task}.`,['represents','represent','representing','are representing'],'The head of the main subject is singular “collection,” despite plural nouns inside its modifiers.','embedded clause','Find the main subject after setting aside the inserted relative clause.'],
  ] as const;const [sentence,choices,rule,structure,trap]=cases[d-1];
  return draft('agreement',structure,`Choose the word or phrase that correctly completes the sentence.\n\n${sentence}`,[...choices],['This finite verb agrees with the actual subject.','This form agrees with a nearby noun or uses the wrong number.','This form does not provide the required finite main verb.','This form has the wrong number, tense, or grammatical function.'],rule,['Identify the head of the subject.', 'Set aside modifiers or identify the nearer coordinated subject.', 'Choose the finite verb that agrees with that subject.'],trap);
};
const possessives:Builder=(d,c)=>{
  const cases=[
    [`One student owns the ${c.item}. Which phrase expresses that meaning?`,[`the student's ${c.item}`,`the students ${c.item}`,`the students' ${c.item}`,`the student's' ${c.item}`],'A singular owner takes apostrophe+s.',['Apostrophe+s marks one student as the owner.','There is no possessive marking.','This indicates more than one student as owner.','Two apostrophes do not form a standard possessive.'],'singular owner'],
    [`Several students jointly own the ${c.item}. Which phrase expresses that meaning?`,[`the students' ${c.item}`,`the student's ${c.item}`,`the students ${c.item}`,`the students's ${c.item}`],'A regular plural owner already ending in s takes an apostrophe after s.',['The apostrophe follows the plural s.','This incorrectly indicates one owner.','The plural has no possessive marking.','Do not add another s to this regular plural possessive.'],'regular plural owner'],
    [`Several children share the ${c.item}. Which phrase correctly expresses ownership?`,[`the children's ${c.item}`,`the childrens' ${c.item}`,`the childrens ${c.item}`,`the childrens's ${c.item}`],'The irregular plural “children” does not end in s, so its possessive is children’s.',['The apostrophe+s follows the complete irregular plural.','“Childrens” is not the plural of child.','The noun is neither a correct plural nor a possessive.','This adds an unnecessary s before the possessive ending.'],'irregular plural owner'],
    [`${c.name} and ${c.other} jointly wrote one report. Which phrase preserves this meaning?`,[`${c.name} and ${c.other}'s report`,`${c.name}'s and ${c.other}'s reports`,`${c.name}'s and ${c.other} report`,`${c.name} and ${c.other}s' report`],'Joint ownership of one item is marked on the last name.',['Only the last name is possessive because the report is shared.','This wording indicates separate reports.','The possessive marking is incomplete and inconsistent.','The name should not be made plural to mark possession.'],'joint possession'],
    [`The museum has two directors. Each director wrote a separate report. Which phrase is clearest and correct?`,["the directors' separate reports","the director's separate reports","the directors separate reports","the directors's separate reports"],'Two directors form a regular plural; the apostrophe follows its s. “Separate” preserves the distinct ownership described.',['Both the plural owners and the separate reports are clear.','The apostrophe before s incorrectly makes one director the owner.','The possessive relation is unmarked.','The plural possessive should not add another s.'],'ownership in context'],
  ] as const;const [text,choices,rule,reasons,structure]=cases[d-1];return draft('possessive-nouns',structure,text,[...choices],[...reasons],rule,['Count the owners before placing an apostrophe.','Form the singular or plural noun.','Mark possession while preserving whether ownership is shared.'],'Do not use an apostrophe merely to form a plural.');
};
const apostrophes:Builder=(d,c)=>d<=3?possessives(d,c):draft('contraction-versus-possession',d===4?'its versus it is':'contractions in a paragraph',`Which revision correctly uses apostrophes?\n\n${d===4?"The club revised it's plan because its too expensive.":"The committee can't adopt the proposal until its clarified whether the revised plan meets it's goals."}`,
  d===4?["The club revised its plan because it's too expensive.","The club revised it's plan because it's too expensive.","The club revised its plan because its too expensive.","The club revised its' plan because it's too expensive."]:["The committee can't adopt the proposal until it's clarified whether the revised plan meets its goals.","The committee cant adopt the proposal until its clarified whether the revised plan meets its goals.","The committee can't adopt the proposal until its clarified whether the revised plan meets it's goals.","The committee can't adopt the proposal until it's clarified whether the revised plan meets it's goals."],
  ['“Its” marks possession; “it’s” contracts “it is” or “it has.”','A contraction is unmarked or possession is mistaken for a contraction.','The required contraction is confused with possession.','The possessive form is incorrectly marked with an apostrophe.'],'Possessive “its” has no apostrophe. Expand “it’s” to “it is” or “it has” to test it.',['Test whether “it is” or “it has” fits each position.','Use it’s for that contraction and its for possession.'],'An apostrophe in a possessive pronoun changes the word into a contraction.');
const pronounCase:Builder=(d,c)=>{
  const cases=[
    [`The librarian handed the ${c.item} to ${c.name} and _____.`,['me','I','my','myself'],'The pronoun is an object of the preposition “to.”','object of preposition'],
    [`_____ and ${c.name} will organize the ${c.plural}.`,['She','Her','Hers','Herself'],'The pronoun is part of the subject of “will organize.”','compound subject'],
    [`Between you and _____, the draft needs more evidence.`,['me','I','my','myself'],'Both coordinated pronouns are objects of “between.”','coordinated objects'],
    [`The director asked ${c.other} and _____ to explain why the ${c.item} had been omitted.`,['him','he','his','himself'],'The pronoun is an object of “asked,” even though an infinitive follows.','object before infinitive'],
    [`The volunteer _____ the staff consulted about the ${c.task} had kept careful notes.`,['whom','who','whose','whoever'],'Inside the relative clause, the staff consulted the volunteer; the relative pronoun is the object.','relative clause case'],
  ] as const;const [sentence,choices,rule,structure]=cases[d-1];return draft('pronoun-case',structure,`Choose the pronoun that correctly completes the sentence.\n\n${sentence}`,[...choices],['The pronoun case matches its grammatical role.','This substitutes subject case for object case, or the reverse.','A possessive form cannot perform the required subject or object role.','A reflexive or indefinite form does not fit this construction.'],rule,['Identify the pronoun’s role inside its own clause.','For a compound phrase, temporarily remove the other noun.','Choose subject or object case to fit that role.'],'Choose pronoun case by grammatical role, not by which form sounds more formal.');
};
const pronounAgreement:Builder=(d,c)=>{
  const cases=[
    [`The two volunteers brought _____ notebooks.`,['their','its','his','her'],'A plural antecedent requires the plural possessive pronoun “their.”','plural antecedent'],
    [`The museum replaced _____ damaged display case.`,['its','their','theirs','they'],'The singular museum takes the singular possessive pronoun “its.”','singular organization'],
    [`The boxes containing the ${c.plural} had lost _____ labels.`,['their','its','it','itself'],'The antecedent is plural “boxes,” not the nearby object inside “containing.”','modified antecedent'],
    [`Neither the guide nor the two visitors remembered to bring _____ tickets.`,['their','its','it','theirs'],'The pronoun refers to the nearer plural antecedent “visitors”; an attributive possessive is needed before tickets.','coordinated antecedent'],
    [`The notebook, unlike the loose pages that ${c.name} had collected, retained _____ original cover.`,['its','their','theirs','they'],'The main antecedent is singular “notebook”; the inserted contrast does not change its number.','interrupted antecedent'],
  ] as const;const [sentence,choices,rule,structure]=cases[d-1];return draft('pronoun-number',structure,`Choose the pronoun that agrees with its antecedent.\n\n${sentence}`,[...choices],['Its number and grammatical form match the intended antecedent.','This uses the wrong number or possessive form.','This form cannot modify the following noun or has the wrong number.','This form does not match the antecedent or its possessive role.'],rule,['Name the noun the pronoun replaces.','Check that noun’s number rather than a nearby modifier.','Choose the possessive form required by the following noun.'],'Singular they is valid English; these items use unambiguous plural or nonhuman singular antecedents instead of treating singular they as an error.');
};
const reference:Builder=(d,c)=>{
 const cases=[
  [`The stated meaning is that ${c.other}, not ${c.name}, will present the project. Which revision removes the ambiguity?\n\nWhen ${c.name} spoke with ${c.other}, they agreed that they would present the project.`,[`When ${c.name} spoke with ${c.other}, they agreed that ${c.other} would present the project.`,`When ${c.name} spoke with ${c.other}, they agreed that they would present it.`,`When ${c.name} spoke with them, they agreed that they would present the project.`,`When ${c.name} spoke with ${c.other}, the project agreed to be presented.`],'name the intended actor'],
  ['The stated meaning is that the folder, not the report, was damaged. Which revision makes the reference clear?\n\nThe assistant placed the report in the folder because it was damaged.',['The assistant placed the report in the damaged folder.','The assistant placed it in the folder because it was damaged.','The assistant placed the damaged report in the folder.','The assistant placed the report in it because it was damaged.'],'distinguish two nonhuman antecedents'],
  [`The stated meaning is that ${c.other} checked the missing page. Which revision makes that action clear?\n\n${c.name} sent ${c.other} a copy of the report. After checking the missing page, they said the report was ready.`,[`${c.name} sent ${c.other} a copy of the report. After ${c.other} checked the missing page, ${c.other} said the report was ready.`,`${c.name} sent ${c.other} a copy of the report. After checking it, they said it was ready.`,`${c.name} sent the report a copy of ${c.other}. It was ready.`,`${c.name} checked the missing page and told ${c.other} the report was ready.`],'reference across sentences'],
  ['The writer wants “This” to refer specifically to comparing the records, not to canceling the meeting. Which revision is clearest?\n\nThe committee compared the records and canceled the meeting. This revealed a missing entry.',['Comparing the records revealed a missing entry.','This revealed that the meeting was a missing entry.','Canceling the meeting revealed a missing entry.','The records and meeting revealed this.'],'vague demonstrative reference'],
  [`The stated facts are that ${c.name} wrote the summary and ${c.other} corrected its dates. Which revision preserves both facts with clear references?\n\nAfter ${c.name} gave ${c.other} the summary, they corrected their dates.`,[`${c.name} wrote the summary and gave it to ${c.other}, who corrected the dates in it.`,`${c.other} wrote the summary and gave it to ${c.name}, who corrected its dates.`,`${c.name} gave ${c.other} their summary, and they corrected their dates.`,`${c.name} and ${c.other} corrected their dates after writing their summaries.`],'two actors and a possessive reference'],
 ] as const;const [text,choices,structure]=cases[d-1];return draft('clear-antecedent',structure,text,[...choices],['The revision names the intended person, object, or action while preserving the source facts.','This leaves the reference unclear or changes the named actor or relationship.','This assigns the action or property to a different antecedent than the prompt specifies.','This remains ambiguous or introduces actions and ownership not established by the source.'],'Replace an unclear pronoun with the specific intended noun or action; a grammatical pronoun can still have an ambiguous reference.',['Identify who or what the pronoun is meant to name according to the source.','Locate other nouns or actions that the pronoun could mistakenly refer to.','Choose the revision that makes the intended reference explicit without changing the facts.'],'Singular they is not inherently incorrect; the error here is an unclear reference or changed meaning.');
};
const tense:Builder=(d,c)=>{
  const cases=[
    [`Yesterday, ${c.name} _____ the ${c.item}.`,['finished','finishes','will finish','has been finishing'],'The completed action occurred yesterday, so simple past fits.','explicit past time'],
    [`Every Saturday, ${c.name} _____ the ${c.plural} before the museum opens.`,['checks','checked','will have checked','had checked'],'A habitual present action requires simple present.','habitual time'],
    [`By the time the visitors arrived yesterday, ${c.other} _____ the display.`,['had arranged','will arrange','arranges','will have arranged'],'The arranging was completed before another past event, so past perfect fits.','past before past'],
    [`By the time the exhibit opens tomorrow, ${c.name} _____ all the ${c.plural}.`,['will have labeled','had labeled','labels yesterday','has label'],'An action completed by a future point uses future perfect.','future completion'],
    [`Which revision correctly shows the order of these past events? The assistant completed the survey first; the director read it later.\n\nWhen the director read the survey, the assistant finishes it.`,['When the director read the survey, the assistant had already finished it.','When the director read the survey, the assistant will finish it.','When the director reads the survey tomorrow, the assistant finished it yesterday.','When the director read the survey, the assistant would be finishing it next week.'],'Past perfect identifies the event completed before the other past event.','ordering past events'],
  ] as const;const [text,choices,rule,structure]=cases[d-1];return draft('time-relations',structure,d===5?text:`Choose the verb phrase that fits the stated time.\n\n${text}`,[...choices],['The tense accurately places the action in the stated time relationship.','The tense conflicts with the stated time or sequence.','This changes the time setting or uses a mismatched form.','This introduces a different time or an incomplete verb phrase.'],rule,['Mark the time of each action.','Determine whether the action is habitual, completed, or earlier than another event.','Select a tense that preserves that relationship.'],'Consistency does not mean every verb must have the same tense; justified time changes require different tenses.');
};
const commas:Builder=(d,c)=>{
  const cases=[
    [`After lunch ${c.name} checked the ${c.plural}.`,[`After lunch, ${c.name} checked the ${c.plural}.`,`After, lunch ${c.name} checked the ${c.plural}.`,`After lunch ${c.name}, checked the ${c.plural}.`,`After lunch ${c.name} checked, the ${c.plural}.`],'A comma separates the introductory phrase from the main clause.','introductory phrase'],
    [`The staff sorted the ${c.plural} scanned the labels and updated the catalog.`,[`The staff sorted the ${c.plural}, scanned the labels, and updated the catalog.`,`The staff sorted, the ${c.plural} scanned the labels and updated the catalog.`,`The staff sorted the ${c.plural} scanned, the labels, and updated the catalog.`,`The staff sorted the ${c.plural}, scanned the labels and, updated the catalog.`],'Commas separate the three parallel actions; they do not separate a verb from its object.','series of actions'],
    [`The ${c.item} was damaged but the staff could still read it.`,[`The ${c.item} was damaged, but the staff could still read it.`,`The ${c.item}, was damaged but the staff could still read it.`,`The ${c.item} was damaged but, the staff could still read it.`,`The ${c.item} was, damaged but the staff could still read it.`],'A comma precedes a coordinating conjunction joining two independent clauses.','coordinated clauses'],
    [`The project has exactly one director. Which punctuation treats the director's name as nonessential information?\n\nThe director ${c.name} welcomed the visitors.`,[`The director, ${c.name}, welcomed the visitors.`,`The director ${c.name}, welcomed the visitors.`,`The director, ${c.name} welcomed the visitors.`,`The director ${c.name} welcomed, the visitors.`],'A nonessential appositive is set off by a matching pair of commas.','nonessential appositive'],
    [`Which revision correctly punctuates the interruption without splitting the main subject from its verb?\n\nThe report which includes several handwritten notes explains how the exhibit was planned.`,['The report, which includes several handwritten notes, explains how the exhibit was planned.','The report, which includes several handwritten notes explains how the exhibit was planned.','The report which includes several handwritten notes, explains how the exhibit was planned.','The report, which includes several handwritten notes, explains, how the exhibit was planned.'],'The nonessential relative clause needs two commas; no extra comma belongs between “explains” and its object clause.','embedded nonessential clause'],
  ] as const;const [text,choices,rule,structure]=cases[d-1];return draft('comma-functions',structure,d>3?text:`Which revision places commas correctly?\n\n${text}`,[...choices],['The commas mark the intended boundaries without breaking a grammatical unit.','The comma separates words that belong together or leaves an interruption unclosed.','The comma is on the wrong side of a boundary or leaves an interruption unopened.','The comma unnecessarily separates a verb from what follows it.'],rule,['Identify the main clause and any introduction, series, or interruption.','Mark both ends of a nonessential interruption.','Do not put a comma between a subject and its verb or a verb and its object.'],'A pause when speaking does not by itself justify a comma.');
};
const dialogue:Builder=(d,c)=>{
  const cases=[
    [`Which sentence punctuates a direct quotation correctly?`,[`"The ${c.item} is ready," ${c.name} said.`,`"The ${c.item} is ready" ${c.name} said.`,`"The ${c.item} is ready." ${c.name} said.`,`"The ${c.item} is ready," ${c.name} Said.`],'A declarative quotation followed by a speech tag ends with a comma inside the closing quotation mark. The speech tag continues the sentence.','following speech tag'],
    [`Which sentence correctly introduces a direct quotation?`,[`${c.name} said, "The ${c.item} is ready."`,`${c.name} said "The ${c.item} is ready."`,`${c.name} said, "the ${c.item} is ready."`,`${c.name}, said "The ${c.item} is ready."`],'A speech tag introducing a complete quotation takes a comma, and the quoted sentence begins with a capital.','preceding speech tag'],
    [`Which sentence correctly punctuates a quoted question and its speech tag?`,[`"Where is the ${c.item}?" ${c.other} asked.`,`"Where is the ${c.item}," ${c.other} asked.`,`"Where is the ${c.item}?", ${c.other} asked.`,`"Where is the ${c.item}?" ${c.other} Asked.`],'The question mark belongs inside the quotation; do not add a comma after it. The speech tag continues with a lowercase verb.','quoted question'],
    [`Which sentence correctly interrupts one quoted sentence with a speech tag?`,[`"When the visitors arrive," ${c.name} said, "we will open the exhibit."`,`"When the visitors arrive," ${c.name} said. "We will open the exhibit."`,`"When the visitors arrive" ${c.name} said "we will open the exhibit."`,`"When the visitors arrive," ${c.name} said, "We will open the exhibit."`],'An interruption inside one quoted sentence is set off by commas; the resumed portion stays lowercase.','interrupted quotation'],
    [`Which revision preserves one complete quoted sentence and correctly punctuates its interruption?\n\nWe should not publish the report the editor explained until we check the figures.`,['"We should not publish the report," the editor explained, "until we check the figures."','"We should not publish the report." The editor explained, "until we check the figures."','"We should not publish the report," the editor explained "Until we check the figures."','"We should not publish the report", the editor explained, "until we check the figures".'],'Commas enclose the speech tag inside a single quotation; the resumed dependent clause begins lowercase, and commas and periods go inside the closing quotation marks.','quotation with dependent continuation'],
  ] as const;const [text,choices,rule,structure]=cases[d-1];return draft('direct-speech',structure,text,[...choices],['The quotation and speech tag form the intended sentence with correct punctuation.','This changes the sentence boundary or omits the required introductory comma.','The punctuation or capitalization breaks the quotation’s intended structure.','The capitalization or placement of punctuation is nonstandard.'],rule,['Determine whether the quoted words are a statement or a question.','Locate the speech tag and decide whether it introduces, follows, or interrupts the quotation.','Keep punctuation and capitalization consistent with those boundaries.'],'A speech tag is part of the sentence; an interrupted quotation does not automatically begin a second sentence.');
};
const capitalization:Builder=(d,c)=>{
  const cases=[
    [`Which sentence uses capitals correctly?`,[`${c.name} visited Brooklyn on Monday.`,`${c.name} visited brooklyn on Monday.`,`${c.name} visited Brooklyn on monday.`,`${c.name} Visited Brooklyn on Monday.`],'People, places, and days are proper names; an ordinary verb is not capitalized.','proper names'],
    [`Which sentence uses capitals correctly?`,[`${c.name} studies English and science.`,`${c.name} studies english and science.`,`${c.name} studies English and Science.`,`${c.name} Studies english and Science.`],'Names of languages are capitalized, but a general school subject such as science is not.','subjects and languages'],
    [`Which sentence uses capitals correctly?`,['We spoke with Director Chen, the museum director.','We spoke with director Chen, the museum director.','We spoke with Director Chen, the Museum Director.','We Spoke with Director Chen, the museum Director.'],'A title directly before a person’s name is capitalized; the same title used generically is lowercase.','title before name'],
    [`Which sentence uses capitals correctly?`,['In April, the class read a book about the American Revolution.','In april, the class read a book about the American revolution.','In April, the Class read a Book about the American Revolution.','In April, the class Read a book about the american Revolution.'],'The month and the formal historical-event name are capitalized; ordinary common nouns and verbs remain lowercase.','historical-event name'],
    [`Which revision correctly capitalizes the complete quoted sentence without capitalizing ordinary job titles?\n\nThe museum director said, the final report will be ready on friday.`,['The museum director said, "The final report will be ready on Friday."','The Museum Director said, "The Final Report will be ready on Friday."','The museum director said, "the final report will be ready on Friday."','The museum director said, "The final report will be ready on friday."'],'A complete quoted sentence begins with a capital, and Friday is a proper name. The generic job title remains lowercase.','quoted sentence and proper noun'],
  ] as const;const [text,choices,rule,structure]=cases[d-1];return draft('capitalization',structure,text,[...choices],['Only sentence beginnings and the required proper names or titles are capitalized.','A required proper name is lowercase or ordinary words are unnecessarily capitalized.','A common noun is treated as a proper name or the quoted sentence starts lowercase.','A required proper name is lowercase or an ordinary verb is capitalized.'],rule,['Identify sentence beginnings and complete quoted sentences.','Separate proper names and formal titles from common nouns.','Capitalize only the required words.'],'A word’s importance does not make it a proper noun.');
};
const modifiers:Builder=(d,c)=>{
  const cases=[
    [`The intended meaning is that ${c.name} used a magnifying glass to examine the ${c.item}. Which sentence is clearest?`,[`Using a magnifying glass, ${c.name} examined the ${c.item}.`,`Using a magnifying glass, the ${c.item} was examined by ${c.name}.`,`The ${c.item}, using a magnifying glass, was examined by ${c.name}.`,`${c.name} examined using a ${c.item} the magnifying glass.`],'The person doing the examining must immediately follow the opening participial phrase.','dangling participial phrase'],
    [`The intended meaning is that the assistant wore a blue coat. Which sentence is clearest?`,['The assistant in a blue coat handed the visitor a ticket.','The assistant handed the visitor a ticket in a blue coat.','The assistant handed the visitor in a blue coat a ticket.','In a blue coat, the ticket was handed to the visitor by the assistant.'],'Place the clothing modifier beside “assistant,” its intended noun.','misplaced prepositional phrase'],
    [`The intended meaning is that ${c.name} sorted the ${c.plural}, but did not scan or label them. Which sentence preserves that meaning?`,[`${c.name} only sorted the ${c.plural}.`,`Only ${c.name} sorted the ${c.plural}.`,`${c.name} sorted only the ${c.plural}.`,`${c.name} sorted the only ${c.plural}.`],'“Only” immediately before “sorted” limits the action rather than the person or objects.','placement of only'],
    [`Which revision clearly states that the volunteers, not the route, completed the survey?\n\nAfter completing the survey, the route was marked on the volunteers' map.`,['After completing the survey, the volunteers marked the route on their map.','After completing the survey, the route marked the volunteers on the map.','After completing the survey, the map marked the route for the volunteers.','After completing the survey, the route was clearly marked on their map.'],'The understood actor of the introductory phrase must be the grammatical subject that follows it.','dangling phrase in passive voice'],
    [`The intended meaning is that the committee approved a plan at a meeting held yesterday, and the plan had been drafted last month. Which revision eliminates the misplaced time modifier?\n\nThe committee approved the plan drafted last month at yesterday's meeting.`,["At yesterday's meeting, the committee approved the plan drafted last month.","The committee approved yesterday's meeting in the plan drafted last month.","The committee drafted the plan at yesterday's meeting and approved it last month.","The plan at yesterday's meeting approved the committee drafted last month."],'Putting the meeting phrase next to the main approval action separates it from the embedded drafting phrase and preserves both dates.','two competing time modifiers'],
  ] as const;const [text,choices,rule,structure]=cases[d-1];return draft('modifier-attachment',structure,text,[...choices],['The modifier attaches to the intended actor, action, or noun.','The modifier attaches to the wrong actor or changes what “only” limits.','The modifier attaches to another noun or reverses the dates.','The revision leaves the modifier dangling or distorts the meaning.'],rule,['State what the modifier is intended to describe.','Identify the noun or action beside it in each choice.','Choose the version that preserves the stated meaning without dangling or misplaced words.'],'A grammatically possible modifier position may still change the intended meaning.');
};
const adjectiveOnly:Builder=(d,c)=>{
  const cases=[
    [`The ${c.item} contains a _____ diagram.`,['clear','clearly','clearness','clarify'],'An adjective describes the noun “diagram.”','noun modifier'],
    [`The museum needs _____ workers to handle the fragile ${c.plural}.`,['careful','carefully','care','carefulness'],'“Careful” describes the workers; the adverb “carefully” would describe an action.','plural noun modifier'],
    ['After the experiment, the room smelled _____.',['sweet','sweetly','sweetness','sweeten'],'Here “smelled” is a linking verb: the adjective describes the room’s smell, rather than how the room performs an action.','sense-verb complement'],
    ['Of the two descriptions, the revised one is _____.',['more detailed','most detailed','more detail','detailedly'],'Use the comparative “more detailed” to compare two descriptions; “most detailed” is a superlative.','comparative in contrast'],
    [`Although the ${c.item} had been repaired, the surface remained _____ and uneven.`,['rough','roughly','roughness','roughen'],'The coordinated adjectives “rough” and “uneven” describe the surface after the linking verb “remained.”','parallel subject complements'],
  ] as const;const [sentence,choices,rule,structure]=cases[d-1];
  return draft('adjective-functions',structure,`Choose the word or phrase that correctly completes the sentence.\n\n${sentence}`,[...choices],['This adjective describes the named noun or makes the required comparison.','This adverb or superlative does not fit the noun description or the stated two-item comparison.','A noun naming a quality does not provide the required descriptive adjective.','This verb or nonstandard adverb cannot fill the required adjective position.'],rule,['Locate the noun or subject being described.','Distinguish a linking-verb description from a description of an action.','Use the adjective form and degree of comparison required by that relationship.'],'Choose an adjective by what it describes, not merely by whether the word sounds familiar.');
};
const adverbOnly:Builder=(d,c)=>{
  const cases=[
    [`${c.name} explained the route _____.`,['clearly','clear','clearness','clarify'],'The adverb “clearly” describes how the explanation was given.','manner of action'],
    [`The volunteers moved _____ so they would not damage the ${c.plural}.`,['carefully','careful','carefulness','care'],'“Carefully” modifies the action “moved,” not the volunteers as a noun.','action in a purpose clause'],
    ['The rewritten instructions were _____ clear.',['remarkably','remarkable','remark','remarkability'],'An adverb can modify an adjective: “remarkably” specifies the degree of “clear.”','degree of adjective'],
    ['The technician worked _____ slowly when separating the fragile pages.',['especially','especial','specialty','special'],'“Especially” is an adverb modifying the adverb “slowly.”','adverb modifying adverb'],
    [`Although ${c.other} had checked the summary, ${c.name} _____ reviewed the original notes before drawing a conclusion.`,['independently','independent','independence','independency'],'“Independently” modifies “reviewed” and describes the manner of the second review; it does not rename or describe the reviewer as a noun.','manner inside a qualified statement'],
  ] as const;const [sentence,choices,rule,structure]=cases[d-1];return draft('adverb-functions',structure,`Choose the word that correctly completes the sentence.\n\n${sentence}`,[...choices],['This adverb modifies the stated action, adjective, or other adverb.','This adjective cannot perform the required adverbial function in the sentence.','This noun names a quality rather than modifying the action or description.','This noun or adjective cannot supply the required adverbial meaning.'],rule,['Find the action, adjective, or adverb being modified.','Ask whether the blank describes how an action occurs or the degree of a description.','Select the grammatical form that expresses that relationship.'],'An adverb is identified by its function; an -ly ending alone does not explain why it fits.');
};
const confused:Builder=(d,c)=>{
  const cases=[
    [`_____ sorting the ${c.plural} before lunch.`,["They're","Their","There","Theirs"],'“They’re” means “they are” and supplies the subject and auxiliary before sorting.','their there they are'],
    [`The club will _____ the donated ${c.plural}.`,['accept','except','expectation','accepted'],'“Accept” means receive; “except” means exclude. A base verb follows will.','accept versus except'],
    ['The revision will _____ the schedule, but its _____ is not yet known.',['affect; effect','effect; affect','affect; affect','effect; effect'],'“Affect” is the verb meaning influence; “effect” is the noun meaning result in this context.','affect and effect'],
    [`The assistant will _____ the ${c.item} on the table after it has been checked.`,['lay','lie','lays','laid'],'“Lay” means put something down and takes a direct object: the item. The modal “will” requires the base form.','lie versus lay with an object'],
    ['The committee needs to _____ the distinction between the _____ proposal and its revised version.',['explain; original','explanation; original','explain; originate','explains; originally'],'After “to,” the base verb “explain” is required; the adjective “original” modifies proposal.','word function in embedded comparison'],
  ] as const;const [sentence,choices,rule,structure]=cases[d-1];return draft('usage-and-word-choice',structure,`Which word or pair correctly completes the sentence?\n\n${sentence}`,[...choices],['Both meaning and grammatical function fit the sentence.','This word has a different meaning or grammatical function.','One required distinction or grammatical form is lost.','The word forms do not fit the required positions.'],rule,['Read the complete sentence to establish the meaning.','Identify the grammatical role of each blank.','Select the words that satisfy both meaning and function.'],'Similar sounds or spellings do not make words interchangeable.');
};
const clause:Builder=(d,c)=>{
  const cases=[
    [`Which group of words is an independent clause?`,[`${c.name} checked the ${c.item}.`,`After checking the ${c.item}`,`Because ${c.name} checked the ${c.item}`,`The ${c.item} on the table`],'An independent clause has a subject and finite verb and expresses a complete thought.','identify complete clause'],
    [`Which group of words is a dependent clause?`,[`Although ${c.name} checked the ${c.item}`,`${c.name} checked the ${c.item}.`,`The ${c.item} was missing.`,`${c.other} found the ${c.item}.`],'“Although” makes the clause dependent despite its subject and finite verb.','subordinating conjunction'],
    [`Which group is a phrase rather than a clause?`,[`Beside the damaged ${c.item}`,`Because the ${c.item} was damaged`,`${c.name} repaired the ${c.item}`,`Although ${c.name} could repair it`],'The prepositional phrase has no subject–finite-verb pair. The other groups are clauses.','phrase versus clause'],
    [`Which portion would be an independent clause if written by itself?\n\nAlthough the room was crowded, ${c.name} explained the report that the committee had requested.`,[`${c.name} explained the report that the committee had requested`,`Although the room was crowded`,`that the committee had requested`,`the report that the committee`],'The main clause has a subject and finite predicate; the although-clause and that-clause depend on it.','main clause with two dependent clauses'],
    ['Which analysis of the sentence is correct?\n\nAfter the students compared the records, the librarian explained why the dates differed.',['The sentence has one independent clause and two dependent clauses.','The sentence has three independent clauses.','The sentence is a fragment because it begins with After.','The sentence has no dependent clauses.'],'“The librarian explained” is the main clause. “After the students compared the records” is an introductory dependent clause, and “why the dates differed” is an embedded dependent clause.','embedded noun clause'],
  ] as const;const [text,choices,rule,structure]=cases[d-1];return draft('clause-boundaries',structure,text,[...choices],['This identifies the grammatical unit and its relation to the main clause.','This treats a dependent unit as independent or selects a complete clause instead of a phrase.','This confuses a complete sentence with a fragment or identifies the wrong unit.','This omits or misclassifies the sentence’s clause relationships.'],rule,['Locate subject–finite-verb pairs.','Check whether a conjunction or relative word makes a clause dependent.','Separate the main complete thought from phrases and dependent clauses.'],'Having a subject and a verb is necessary for a clause but does not make every clause independent.');
};
const phraseOnly:Builder=(d,c)=>{
  const cases=[
    [`Which group is a phrase rather than a clause?`,[`Beside the damaged ${c.item}`,`Because the ${c.item} was damaged`,`${c.name} repaired the ${c.item}`,`Although ${c.name} could repair it`],'The prepositional phrase has no subject–finite-verb pair.','prepositional phrase'],
    ['Which group is a phrase rather than a clause?',['Carefully examining the original map','While the assistant examined the map','The assistant examined the map','Although the map had faded'],'The participial phrase has no subject with a finite verb; “examining” alone does not make a clause.','participial phrase'],
    ['Which group is an appositive phrase that renames “the guide”?\n\nThe guide, a volunteer with years of experience, explained the route.',['a volunteer with years of experience','The guide explained the route','who explained the route','because the route was unfamiliar'],'The noun phrase renames the guide without adding a subject–finite-verb pair.','appositive phrase'],
    ['Which group is a phrase rather than a clause?',['To compare the records before making a decision','Before the librarian made a decision','Why the records did not match','The librarian compared the records.'],'The infinitive phrase has no subject–finite-verb pair; “to compare” is not a finite verb.','infinitive phrase'],
    ['Which bracketed group is a phrase rather than a clause?\n\n[After the committee reviewed the draft], the editor, [a reader familiar with the original sources], asked [why the dates differed] and explained [that another record was missing].',['a reader familiar with the original sources','After the committee reviewed the draft','why the dates differed','that another record was missing'],'The appositive noun phrase lacks a finite predicate; the other three groups contain their own subjects and finite verbs.','phrase among embedded clauses'],
  ] as const;const [text,choices,rule,structure]=cases[d-1];return draft('phrase-boundaries',structure,text,[...choices],['This noun, prepositional, participial, or infinitive group lacks its own subject–finite-verb pair.','This group contains a subject and finite verb, so it is a clause rather than the requested phrase.','This group has a clause-level predicate or does not supply the requested appositive.','This group contains a dependent clause or a noun modified by a clause rather than the specified phrase.'],rule,['Look for a subject and its finite verb inside each candidate.','Distinguish infinitives and participles from finite main verbs.','Identify the group whose function is that of a phrase.'],'A long phrase is still a phrase; word count does not turn it into a clause.');
};
const independentOnly:Builder=(d,c)=>{
  if(d===1)return clause(1,c);
  if(d===4)return clause(4,c);
  const cases=d===2?[
    'Which group is an independent clause?',['Check the label before opening the case.','Before opening the case','Because the label was missing','The case beside the door'],'An imperative has an understood subject “you” and a finite main verb, so it can express a complete instruction.','imperative clause',
  ] as const:d===3?[
    'Which group can stand alone as a complete sentence?',['The room was crowded, but the guide could still reach the display.','Although the room was crowded','The guide who reached the display','After the guide had reached the display'],'Two independent clauses joined by comma+but form a complete sentence; the other groups lack a complete main thought.','coordinated main clauses',
  ] as const:[
    'Which quoted portion is the complete independent clause of this sentence?\n\nAfter the archivist checked the first ledger, she explained why the second list, which had been copied later, differed.',['she explained why the second list, which had been copied later, differed','After the archivist checked the first ledger','which had been copied later','why the second list differed'],'The main clause begins with “she explained”; its embedded why-clause does not make the whole main clause dependent.','main clause with nested content',
  ] as const;const [text,choices,rule,structure]=cases;return draft('independent-clause-identification',structure,text,[...choices],['This group supplies a complete main thought with its own subject and finite predicate.','The introductory word makes this group dependent on a main clause.','This relative or noun group cannot stand alone as the intended complete sentence.','This dependent group does not state the whole main thought.'],rule,['Locate the main finite predicate and its subject, including an understood you in commands.','Set aside introductory and relative clauses.','Choose the complete main thought rather than a subordinate portion.'],'A complete main clause may contain dependent clauses without becoming dependent itself.');
};
const dependentOnly:Builder=(d,c)=>{
  if(d===2)return clause(2,c);
  if(d===1)return draft('dependent-clause-identification','because clause','Which group is a dependent clause?',[`Because ${c.name} lost the ${c.item}`,`${c.name} found the ${c.item}.`,`The ${c.item} was useful.`,`${c.other} returned the ${c.item}.`],['Because introduces a clause that depends on a main clause to complete its thought.','This group expresses a complete thought with no subordinating word.','This is a complete main clause rather than a subordinate group.','This is an independent clause with a subject and finite verb.'],'The conjunction because makes its subject–verb group dependent on a main clause.',['Locate the group introduced by a subordinating conjunction.','Confirm that it has a subject and finite verb.','Distinguish a reason clause from the complete main thought it supports.'],'A subject and verb do not make a clause independent when a subordinating word makes it depend on another clause.');
  const cases=d===3?[
    'Which quoted portion is a dependent clause?\n\nThe visitor who found the missing page gave it to the librarian.',['who found the missing page','The visitor gave it to the librarian','gave it to the librarian','the missing page'],'The relative pronoun “who” introduces a clause that modifies visitor and cannot stand alone.','relative clause',
  ] as const:d===4?[
    'Which group is a dependent clause functioning as the object of “explained”?\n\nThe librarian explained why the dates differed.',['why the dates differed','The librarian explained','the librarian','the dates'],'The why-clause contains a subject and finite verb but functions as the content of the main explanation.','embedded noun clause',
  ] as const:[
    'Which statement correctly identifies the dependent clauses?\n\nAfter the students compared the records, the librarian explained why the dates differed.',['“After the students compared the records” and “why the dates differed” are dependent clauses.','Only “the librarian explained” is a dependent clause.','Every group containing a verb is an independent clause.','The sentence has no dependent clauses because it is complete.'],'The introductory after-clause and embedded why-clause depend on the main clause “the librarian explained.”','multiple subordinate functions',
  ] as const;const [text,choices,rule,structure]=cases;return draft('dependent-clause-identification',structure,text,[...choices],['This identifies a subordinate clause by its introductory word and function in the main sentence.','This selects or mislabels the main independent clause instead of the subordinate content.','A finite verb alone does not establish that a clause is independent.','A complete sentence can contain dependent clauses or noun phrases within it.'],rule,['Locate the subject and finite verb inside the candidate group.','Check for a subordinating conjunction, relative pronoun, or content-clause role.','Distinguish that dependent function from the main complete thought.'],'A dependent clause may contain a subject and verb; dependence comes from its grammatical relationship.');
};
const fragments:Builder=(d,c)=>{
 const cases=[
  [`Because the ${c.item} was damaged. ${c.name} made a copy.`,[`Because the ${c.item} was damaged, ${c.name} made a copy.`,`Because the ${c.item} was damaged, making a copy.`,`The ${c.item} was damaged, ${c.name} made a copy.`,`Because the ${c.item} was damaged ${c.name}. Made a copy.`],'Attach the because-clause to a complete main clause.','dependent-clause fragment'],
  [`The volunteers reviewing the ${c.plural} before the museum opened.`,[`The volunteers reviewed the ${c.plural} before the museum opened.`,`The volunteers reviewing the ${c.plural}, before the museum opened.`,`Because the volunteers reviewing the ${c.plural} before the museum opened.`,`The volunteers who reviewing the ${c.plural} before the museum opened.`],'Reviewing is not a finite main verb without an auxiliary; reviewed completes the predicate.','participial fragment'],
  ['The pattern that the designer revised after the first fitting.',['The pattern that the designer revised after the first fitting now fits the actor.','The pattern that the designer revising after the first fitting.','Because the pattern that the designer revised after the first fitting.','The pattern, that the designer revised, after the first fitting.'],'The relative clause modifies pattern but does not supply the noun’s main predicate; adding now fits the actor does.','subject with relative-clause fragment'],
  ['A record containing dates that differed from the published list.',['A record containing dates that differed from the published list was found in the archive.','A record containing dates that differed from the published list, in the archive.','Because a record containing dates that differed from the published list.','A record, containing dates, that differed from the published list.'],'The subject noun phrase has a dependent clause inside it but still needs a main predicate, supplied by was found.','embedded-clause noun-phrase fragment'],
  ['Although the crew tested the revised prototype twice. It still performed poorly under heavy loads.',['Although the crew tested the revised prototype twice, it still performed poorly under heavy loads.','Although the crew tested the revised prototype twice, still performing poorly under heavy loads.','The crew tested the revised prototype twice, it still performed poorly under heavy loads.','Although the crew testing the revised prototype twice, it still performing poorly under heavy loads.'],'The although-clause must connect to the finite main clause while preserving the contrast between testing and poor performance.','concession across sentence boundary'],
 ] as const;const [source,choices,rule,structure]=cases[d-1];return draft('fragment-repair',structure,`Which revision produces a complete sentence and preserves the stated action or relationship?\n\n${source}`,[...choices],['The sentence includes a finite main predicate and preserves the given action or relationship.','The revision still lacks a finite main predicate or remains an incomplete noun group.','A dependent group is still unattached, or two complete clauses are joined by a comma alone.','Added punctuation does not supply the missing main predicate or repair the verb forms.'],rule,['Separate the main subject from any phrases or dependent clauses inside it.','Locate the missing main predicate or unattached subordinate clause.','Choose a complete revision while preserving the source’s relationship.'],'A clause embedded inside a subject does not supply that subject’s main predicate; punctuation alone cannot repair a fragment.');
};
const runons:Builder=(d,c)=>{
 const cases=[
  [`The ${c.item} was damaged ${c.name} made a copy.`,[`The ${c.item} was damaged; ${c.name} made a copy.`,`The ${c.item} was damaged, ${c.name} made a copy.`,`The ${c.item} was damaged ${c.name}, made a copy.`,`The ${c.item} was damaged; and because ${c.name} made a copy.`],'fused clauses'],
  ['The orchestra stored its cases downstairs the narrow staircase made carrying them difficult.',['The orchestra stored its cases downstairs; the narrow staircase made carrying them difficult.','The orchestra stored its cases downstairs, the narrow staircase made carrying them difficult.','The orchestra stored its cases; downstairs the narrow staircase made carrying, them difficult.','The orchestra stored its cases downstairs the narrow staircase, made carrying them difficult.'],'independent clauses with different subjects'],
  ['The revised method was faster, however, the committee needed to check its accuracy.',['The revised method was faster; however, the committee needed to check its accuracy.','The revised method was faster, however the committee needed to check its accuracy.','The revised method was faster however, the committee needed to check its accuracy.','The revised method was faster; however the committee, needed to check its accuracy.'],'conjunctive-adverb boundary'],
  ['The record that the archivist found listed three dates the published account listed only two.',['The record that the archivist found listed three dates; the published account listed only two.','The record that the archivist found listed three dates, the published account listed only two.','The record that the archivist found; listed three dates the published account listed only two.','The record that the archivist found listed three dates the published account; listed only two.'],'boundary after a relative-clause subject'],
  ['Although the team checked the first draft, an error remained the editor noticed it, but the issue had already been printed.',['Although the team checked the first draft, an error remained; the editor noticed it, but the issue had already been printed.','Although the team checked the first draft, an error remained, the editor noticed it, but the issue had already been printed.','Although the team checked the first draft; an error remained the editor noticed it, but the issue had already been printed.','Although the team checked the first draft, an error remained the editor; noticed it, but the issue had already been printed.'],'subordination and coordinated clause boundaries'],
 ] as const;const [source,choices,structure]=cases[d-1];return draft('independent-clause-repair',structure,`Which revision correctly marks the boundaries between complete clauses?\n\n${source}`,[...choices],['A semicolon marks the boundary between complete clauses, and any conjunction or conjunctive adverb is punctuated correctly.','A comma alone does not join the complete clauses at the disputed boundary.','This boundary punctuation splits a clause or fails to mark the boundary between complete clauses.','This punctuation splits a subject from its predicate or leaves the clause boundary unmarked.'],'Join independent clauses with a period, a semicolon, or a comma plus a coordinating conjunction. “However” is not a coordinating conjunction.',['Set aside introductory and relative clauses to find each complete main thought.','Locate the boundary between independent clauses rather than inside a subject–predicate unit.','Choose the punctuation appropriate to the connector used at that boundary.'],'An embedded clause may make the sentence longer, but punctuation must still mark the boundaries of the main complete thoughts.');
};
const commaSplices:Builder=(d,c)=>{
  const item=runons(d,c);return {...item,structure:`comma-splice:${item.structure}`,text:`Which revision corrects the comma splice while preserving the stated ideas?\n\n${item.choices[0].replace(';',',')}`};
};
const combining:Builder=(d,c)=>{
  if(d===2)return draft('combine-cause-after-result','result before reason',`Which combination preserves the stated result and its reason?\n\n${c.name} made a readable copy of the ${c.item}. The original had faded.`,[`${c.name} made a readable copy of the ${c.item} because the original had faded.`,`${c.name} made the original fade by creating a readable copy of the ${c.item}.`,`Although the original had never faded, ${c.name} made a readable copy of the ${c.item}.`,`${c.name} made a readable copy of the ${c.item}, the original had faded.`],['The combination keeps the copy as the response to the faded original.','This reverses the cause: the copy did not make the original fade.','This contradicts the source fact that the original had faded.','A comma alone improperly joins the two complete clauses.'],'A causal combination must keep the reason and result in their original relationship.',['Identify which fact is the cause and which is the response.','Use because to attach the reason to the main result.','Reject reversals, contradictions, and comma splices.'],'Putting the result first does not change what caused it; preserve the source relationship.');
  if(d===4)return draft('combine-preserving-condition','conditional action and pending evidence','Which combination preserves both the condition and the reason for waiting?\n\nThe committee would adopt the new schedule if the survey represented all grades. That had not yet been confirmed. The committee kept the current schedule for now.',['Because it had not yet been confirmed that the survey represented all grades, the committee kept the current schedule while considering a conditional change.','The survey definitely represented every grade, so the committee immediately adopted the new schedule.','The committee rejected every future change because surveys can never represent all grades.','The committee adopted the schedule, the survey was not confirmed, keeping the current schedule.'],['The sentence keeps the proposed change conditional and the temporary decision dependent on missing confirmation.','This changes both the uncertainty and the committee’s actual decision.','This introduces an absolute rejection absent from the source.','The comma-spliced construction also makes the adopted and current schedules conflict.'],'Combining statements must preserve conditional proposals and distinguish them from actions already taken.',['Separate the condition for a possible change from the current decision.','Connect the missing confirmation to the reason for waiting.','Retain the difference between a proposal and an adopted action.'],'A possible action under a condition is not an action that has already happened.');
  const before=d<3?`The ${c.item} was damaged. ${c.name} made a copy because of the damage.`:d<5?'The revised method was faster. Its accuracy had not been tested. The committee kept the earlier method temporarily.':'The pilot reached more participants than the old method. Some participants lacked internet access. A paper option remained necessary.';
  const choices:Draft['choices']=d<3?[`Because the ${c.item} was damaged, ${c.name} made a copy.`,`The ${c.item} was damaged, ${c.name} made a copy.`,`Although ${c.name} made a copy, the ${c.item} could not have been damaged.`,`${c.name} damaged the ${c.item} by making a copy.`]:d<5?['Although the revised method was faster, its accuracy had not been tested, so the committee temporarily kept the earlier method.','The revised method was faster, so the committee knew it was accurate and kept it permanently.','The revised method was faster, its accuracy had not been tested, the committee kept the earlier method.','Because the earlier method was faster, the committee could not test the revised method.']:['Although the pilot reached more participants than the old method, a paper option remained necessary for participants without internet access.','The pilot reached every participant, so the paper option was no longer necessary.','Because a paper option remained necessary, the pilot reached fewer participants than the old method.','The pilot reached more participants than the old method, a paper option was necessary, internet access.'];
  return draft('combine-preserving-relations',d<3?'cause in two sentences':d<5?'contrast and consequence':'qualified comparison',`Which combination preserves all the stated ideas and their relationship?\n\n${before}`,choices,['The relationship and all necessary qualifications are preserved in a complete sentence.','This changes the facts or creates a comma splice.','This reverses the relationship or joins independent clauses with commas alone.','This changes the cause or leaves an incomplete sentence.'],'Combining sentences must preserve their logical relationships, not merely remove periods.',['List the facts and the relationship between them.','Choose a connector that expresses that relationship.','Check completeness and retain any qualification.'],'A fluent sentence is still wrong if it changes the source facts or causal direction.');
};
type RevisionContext={title:string;paragraph:string;claim:string;support:string;irrelevant:string;conclusion:string;introduction:string;limit:string;audience:string;source:string;precise:string;wordy:string;concise:string};
const revisionContexts:RevisionContext[]=[
  {title:'Lost-and-found labels',paragraph:'(1) The school’s lost-and-found table was difficult to use. (2) Unlabeled bags were mixed with jackets and lunch boxes. (3) Volunteers sorted the items into labeled sections. (4) Students could then look in the section for the item they had lost. (5) The gym floor had been polished the night before.',claim:'Grouping lost items into labeled sections can make them easier to find.',support:'During the trial, a student found a lunch box by going directly to the labeled lunch-box section.',irrelevant:'Sentence5',conclusion:'Clear categories helped students search for missing belongings.',introduction:'A small change in organization can make a crowded lost-and-found table easier to use.',limit:'The paragraph describes this school’s trial, not every possible lost-and-found system.',audience:'a school newsletter',source:'The volunteers sorted thirty jackets, twenty bags, and ten lunch boxes into separate labeled sections.',precise:'The volunteers sorted sixty items into three labeled sections.',wordy:'The volunteers made a plan to prepare and get ready to sort the items.',concise:'The volunteers planned to sort the items.'},
  {title:'A seed exchange',paragraph:'(1) The library began a small seed exchange. (2) Donors put seed packets in drawers marked with plant names. (3) A card in each drawer explained when to plant those seeds. (4) Visitors could borrow packets and later return seeds they had collected. (5) The library’s oldest window faced the parking lot.',claim:'Labels and planting information made the library’s seed exchange easier to use.',support:'A visitor used the card in the bean drawer to determine when to plant the borrowed beans.',irrelevant:'Sentence5',conclusion:'The drawers offered both seeds and the information needed to begin growing them.',introduction:'A library can share practical growing knowledge as well as books.',limit:'Having planting information helps visitors begin; it does not guarantee that every seed will grow.',audience:'an informational library brochure',source:'Visitors borrowed eighteen bean packets and twelve lettuce packets during the first week; no other packets were borrowed.',precise:'Visitors borrowed thirty seed packets in the first week.',wordy:'Each drawer contained a card that provided information and informative details about planting.',concise:'Each drawer contained planting information.'},
  {title:'Two rain barrels',paragraph:'(1) A garden club compared two ways of connecting a rain barrel to a downspout. (2) In one storm, the direct connection collected more water than the loose funnel. (3) The club did not measure how either design performed in heavier storms. (4) It decided to keep testing before recommending one design for every garden. (5) Some volunteers wore green shirts.',claim:'One trial favored the direct connection, but more testing was needed before making a general recommendation.',support:'In the measured storm, the direct connection collected eighteen liters, while the loose funnel collected eleven.',irrelevant:'Sentence5',conclusion:'The promising result justified another test rather than a recommendation for all conditions.',introduction:'A useful test can reveal both a promising design and the limits of the available evidence.',limit:'Only one storm was measured, so the result cannot establish performance in all storms.',audience:'a formal garden-club report',source:'In one measured storm, the direct connection collected eighteen liters and the loose funnel collected eleven liters.',precise:'The direct connection collected seven liters more than the loose funnel in the measured storm.',wordy:'In the one initial first trial, the direct connection collected a greater amount of more water.',concise:'In the initial trial, the direct connection collected more water.'},
  {title:'Participation and access',paragraph:'(1) A neighborhood group collected comments on a proposed playground. (2) Online responses arrived faster than the previous paper responses. (3) However, several residents told the group that they did not have reliable internet access. (4) The group retained a paper option to include those residents. (5) The new online form used a blue border.',claim:'A faster online response process still needs an accessible alternative for residents without reliable internet.',support:'Three residents without home internet submitted their comments using the retained paper option.',irrelevant:'Sentence5',conclusion:'Keeping both methods allowed the group to combine speed with wider access.',introduction:'An efficient feedback system is useful only if the intended participants can use it.',limit:'Response speed alone does not measure how well a process reaches every intended participant.',audience:'a report to a neighborhood council',source:'Twenty online comments arrived in two days; six paper comments arrived within a week, including three from residents without home internet.',precise:'The group received twenty-six comments through its two response methods.',wordy:'The online form was quicker in speed, but a paper option was still necessary and needed.',concise:'The online form was faster, but a paper option was still necessary.'},
  {title:'What an archive can establish',paragraph:'(1) Students studying an old neighborhood fair found a ledger listing nine exhibitors. (2) A newspaper photograph showed two stalls whose signs did not match any ledger entry. (3) The ledger may therefore be incomplete, although the photograph alone does not establish how many exhibitors were omitted. (4) The students searched for additional records before announcing a final total. (5) The ledger’s cover had faded to pale brown.',claim:'Conflicting records suggest an incomplete ledger but do not establish the fair’s final exhibitor total.',support:'Two visible stall signs in the photograph corresponded to no name in the ledger.',irrelevant:'Sentence5',conclusion:'Additional records were needed to distinguish a probable omission from a verified total.',introduction:'Historical records can be informative without being complete.',limit:'Evidence of at least one omission does not establish the total number of missing entries.',audience:'a careful historical-research summary',source:'The ledger listed nine exhibitors, and the photograph showed two unmatched stall signs; whether the signs represented separate exhibitors was not established.',precise:'The photograph raised a question about the ledger’s completeness without establishing a new exhibitor total.',wordy:'The evidence of records that did not match each other established that there was a mismatch, but not a final total number.',concise:'The conflicting records suggested an omission but did not establish a final total.'},
];
const applicationRevisionContexts:RevisionContext[]=[
  {title:'Readable bus notices',paragraph:'(1) Riders sometimes waited at a bus stop after its temporary closure. (2) The closure notice used small print below an advertisement. (3) A student group proposed a larger notice beside the stop number. (4) Its draft also named the nearest open stop. (5) One student owned a yellow backpack.',claim:'A noticeable closure sign should also tell riders where they can catch the bus.',support:'Three riders who saw the trial notice walked to the named open stop instead of waiting at the closed stop.',irrelevant:'Sentence5',conclusion:'The draft addressed both noticing the closure and knowing what to do next.',introduction:'Useful public instructions must be easy to notice and give people a next step.',limit:'The trial shows what happened to three riders, not every rider at every stop.',audience:'a transit information proposal',source:'The notice identified the closed stop and named the nearest open stop, located one block east.',precise:'The notice directed riders to the nearest open stop, one block east.',wordy:'The notice gave directions explaining where riders should go to reach the location of the open stop.',concise:'The notice directed riders to the open stop.'},
  {title:'Reading by interest',paragraph:'(1) Students asked the library for summer reading suggestions. (2) Some wanted short mysteries, while others preferred books about animals. (3) The librarian grouped recommendations by interest and included each book’s length. (4) The list did not rank one kind of reader above another. (5) The librarian’s desk stood beside a green wall.',claim:'Organizing recommendations by interest and length lets readers find suitable books without treating one preference as superior.',support:'A reader looking for a short mystery could use both the mystery heading and the listed page counts.',irrelevant:'Sentence5',conclusion:'The list offered a route to a suitable choice rather than a single choice for everyone.',introduction:'A helpful reading list can guide different readers without assuming they all want the same book.',limit:'A recommendation can guide a choice without guaranteeing that every reader will enjoy it.',audience:'a library information page',source:'The list grouped books by subject and genre, and supplied page counts; it did not publish ratings or a ranking.',precise:'The list combined interest categories with page counts rather than ranking the books.',wordy:'The list was arranged and organized in an order that grouped books into groups by interest.',concise:'The list grouped books by interest.'},
  {title:'A quiet gallery trial',paragraph:'(1) A museum tried a quiet visiting hour on Wednesday. (2) During that hour, visitors could enter a room with its recorded soundtrack turned off. (3) Several visitors said the quieter room helped them attend to the artwork. (4) Since the museum collected comments only from Wednesday’s visitors, it planned another trial on the weekend. (5) The entrance mat was striped.',claim:'The Wednesday comments supported another quiet-hour trial, but did not establish every visitor’s preference.',support:'Six Wednesday visitors reported that switching off the soundtrack helped them concentrate on the displayed drawings.',irrelevant:'Sentence5',conclusion:'The initial comments justified a broader test rather than a claim about every visitor.',introduction:'A museum can try an access change while continuing to investigate whom it helps.',limit:'Wednesday’s volunteers may not represent the people who visit on other days.',audience:'a museum access report',source:'Six visitors offered comments during Wednesday’s quiet hour; no weekend visitors were surveyed.',precise:'Six Wednesday visitors commented on the quiet hour, while weekend preferences remained unmeasured.',wordy:'The museum planned to test again in another additional trial on the weekend.',concise:'The museum planned another trial on the weekend.'},
  {title:'Headlines and scope',paragraph:'(1) The school paper reported a survey of students in one art class. (2) Most respondents preferred an earlier exhibition time. (3) The first headline announced that all students wanted the change. (4) The editors replaced that headline with one that named the surveyed class and described a majority rather than everyone. (5) The editor’s pencil case contained three erasers.',claim:'A headline should preserve who was surveyed and how widely the preference was shared.',support:'The revised headline read “Most Respondents in One Art Class Favor Earlier Exhibition.”',irrelevant:'Sentence5',conclusion:'The revised headline made the finding useful without turning it into a schoolwide claim.',introduction:'Short reporting can remain accurate when it keeps the boundaries of its evidence.',limit:'A majority in one class does not establish unanimous support throughout the school.',audience:'a factual school-news report',source:'Eighteen of twenty-five respondents in one art class favored an earlier time; no other classes were surveyed.',precise:'A majority of respondents in the surveyed art class favored an earlier exhibition time.',wordy:'Most of the majority of respondents who answered in the one single class preferred an earlier time.',concise:'Most respondents in the surveyed class preferred an earlier time.'},
  {title:'What changed at the park?',paragraph:'(1) A neighborhood group counted more park visitors after new trail signs were installed. (2) The second count was made during a holiday weekend, unlike the first. (3) The increase therefore could not be attributed to the signs alone. (4) The group proposed comparing similar weekends before judging the signs’ effect. (5) The counting sheet was clipped to a purple board.',claim:'The higher visitor count is worth investigating, but the holiday difference prevents attributing the increase to the signs alone.',support:'The first count was made on an ordinary weekend, while the second coincided with a school holiday.',irrelevant:'Sentence5',conclusion:'Comparable observations would be needed to separate the signs’ possible effect from the holiday’s effect.',introduction:'An apparent improvement can invite further inquiry without proving what caused it.',limit:'Two conditions changed between the counts, so the observations do not isolate a single cause.',audience:'a careful neighborhood planning report',source:'Visitor counts increased after the signs were installed, but the second observation also fell on a holiday weekend.',precise:'The higher count followed both the installation of signs and a change to a holiday weekend.',wordy:'The new signs may possibly have perhaps contributed to an increase, but the holiday might also have made a contribution.',concise:'The signs or the holiday could have contributed to the increase.'},
];
const organization=(label:string,source:RevisionContext[]=revisionContexts):Builder=>(d)=>{
  const c=source[d-1];const shown=c.paragraph;
  if(['Introductions','Topic sentences'].includes(label))return draft(label==='Introductions'?'whole-text-opening':'paragraph-focus','focus then details',`Which ${label==='Introductions'?'opening':'topic'} sentence best prepares readers for the ideas in this paragraph?\n\n${shown}`,[c.introduction,'Every project succeeds as soon as its first plan is written.','The color of a building determines the quality of its work.','No useful conclusion can ever be drawn from a written record.'],['This opening introduces the paragraph’s actual focus without claiming more than its details support.','This universal claim is unsupported by the paragraph.','Building color is unrelated to the paragraph’s development.','The paragraph uses records or observations productively rather than rejecting them all.'],'An introduction or topic sentence should name the idea that the relevant details develop.',['Identify the shared focus of the relevant details.','Choose an opening broad enough to include those details.','Reject claims the paragraph never establishes.'],'An opening should guide the reader, not exaggerate the paragraph’s conclusion.');
  if(label==='Conclusions')return draft('qualified-conclusion','details then synthesis',`Which concluding sentence best follows this paragraph?\n\n${shown}`,[c.conclusion,'This result proves that the same method is best under every possible condition.','Therefore, collecting any further information would always be pointless.','In conclusion, the appearance of the building was the main issue.'],['This synthesizes the paragraph’s central finding while retaining its limits.','The paragraph does not support a universal conclusion.','The observations do not make further evidence universally useless.','The paragraph’s central issue is not the building’s appearance.'],'A conclusion should synthesize the developed idea without adding an unsupported generalization.',['Identify the finding and its limitation.','Choose the sentence that closes that line of thought.','Check that it adds no new unproved claim.'],'A strong-sounding universal claim is weaker than a supported, qualified conclusion.');
  if(['Sentence placement','Paragraph placement','Reordering'].includes(label)){
    if(label==='Paragraph placement')return draft('paragraph-order','evidence before qualification',`A report contains these paragraphs. Which order makes the development clearest?\n\nParagraphA: ${c.conclusion} ${c.limit}\nParagraphB: ${c.introduction}\nParagraphC: ${shown}`,
      ['B, C, A','A, B, C','C, A, B','B, A, C'],['The opening introduces the focus, the middle supplies details, and the ending interprets them.','The interpretation appears before the topic and evidence are introduced.','The introduction arrives after the evidence and conclusion.','The conclusion appears before the evidence it synthesizes.'],'A report normally introduces its question, develops evidence, and then interprets what that evidence establishes.',['Identify the paragraph that introduces the topic.','Place specific evidence after that introduction.','Put the synthesis and qualification after the evidence.'],'The most general paragraph is not automatically a conclusion; follow its function.');
    return draft('reference-and-sequence','referent before reference',`Which order makes these three sentences coherent?\n\n(1) ${c.conclusion}\n(2) ${c.introduction}\n(3) ${c.support}`,
      ['2, 3, 1','1, 2, 3','3, 1, 2','2, 1, 3'],['The focus comes first, the supporting example next, and the interpretation last.','The conclusion precedes its explanation.','The topic arrives after its example and conclusion.','The conclusion is stated before the supporting example.'],'Sequence sentences according to their function: introduce, support, synthesize.',['Identify the sentence introducing the subject.','Locate the concrete supporting observation.','Place the conclusion after the support.'],'Do not order sentences by length or vocabulary; order them by the ideas they require.');
  }
  if(label==='Transitions'){
    const cases=[
      ['The drawers were clearly labeled. _____, visitors could go directly to the section they needed.',['As a result','In contrast','Nevertheless','Before that'],'cause and result','The second sentence is a result of the clear labels.'],
      ['The list could guide readers with different interests. _____, a reader seeking a short mystery could check both a heading and a page count.',['For example','In contrast','Consequently','Previously'],'general claim and example','The second sentence supplies a specific instance of the general guidance.'],
      ['The first method produced a promising result. _____, one trial could not establish its performance under all conditions.',['However','As a result','For example','Similarly'],'finding and qualification','The second sentence limits what can be concluded from the promising result.'],
      ['The application allowed online responses. _____, a paper version was available for residents without reliable internet.',['In addition','On the contrary','As a result','Beforehand'],'complementary features','The second sentence adds another access route rather than opposing or resulting from the first.'],
      ['The photograph suggested an omission. _____, it did not establish the final total.',['Nevertheless','Therefore','For instance','Likewise'],'implication and evidentiary limit','The second sentence qualifies the possible implication without giving a result, example, or parallel finding.'],
    ] as const;const [sentence,choices,structure,rule]=cases[d-1];return draft('logical-connectors',structure,`Which transition accurately connects the two ideas?\n\n${sentence}`,[...choices],[`This connector expresses the actual relationship: ${rule}`,'This connector states a contrast or consequence that the two sentences do not establish.','This connector gives an example or causal result when that is not the stated relationship.','This connector imposes a time sequence or similarity absent from the relationship.'],rule,['Summarize each idea separately before selecting a connecting phrase.','Identify whether the second idea is an example, addition, consequence, or qualification.','Select a connector that accurately names that relationship.'],'A fluent connector can still change the argument; check the logical relationship between the sentences.');
  }
  return draft('coherent-development','focus and reference',`Which revision would most improve the ${label.toLowerCase()} of this paragraph?\n\n${shown}`,
    ['Remove sentence5, which does not develop the paragraph’s central idea.','Move sentence5 to the beginning and remove the main finding.','Remove the concrete evidence and keep only sentence5.','Replace the central finding with a claim that every method always works.'],['The unrelated detail interrupts the development of the stated focus.','This makes the unrelated detail the focus and deletes the main finding.','This removes the paragraph’s support instead of the interruption.','This introduces an unsupported universal claim.'],'Cohesion, coherence, and organization require sentences to develop a clear shared focus and understandable relationships.',['Identify the paragraph’s central focus.','Test each sentence’s contribution to that focus.','Remove the interruption without deleting necessary evidence or qualifications.'],'A sentence can be true and grammatically correct while still interrupting a paragraph’s purpose.');
};
const revision=(label:string,source:RevisionContext[]=revisionContexts):Builder=>(d,c)=>{
  const r=source[d-1];
  if(label==='Main claim')return draft('central-claim','paragraph to proposition',`Which sentence best states the main claim supported by this draft?\n\n${r.paragraph}`,[r.claim,'The project proved that one method was best for everyone in every situation.','The appearance of the materials mattered more than the project’s purpose.','The people involved had no reason to collect information.'],['This statement includes the main idea and retains its scope.','The draft does not prove a universal result.','An incidental appearance detail is not the supported claim.','The draft gives a practical reason for using information.'],'A main claim should unite the relevant details and match the strength of the available evidence.',['Separate the main evidence from incidental detail.','State what the evidence establishes.','Retain any limitation on that conclusion.'],'Do not convert a local observation into a universal claim.');
  if(['Supporting details','Relevant information','Evidence','Sentence addition'].includes(label))return draft('relevant-support','claim plus new evidence',`The writer wants to support this claim: “${r.claim}” Which sentence would add the most relevant evidence?\n\n${r.paragraph}`,[r.support,'Some of the participants liked the color blue.','The writer believed that every future project would be successful.','The building contained several windows of different sizes.'],['This concrete observation directly supports the stated claim.','Color preferences do not support the claim.','A belief about future success is not evidence for this claim.','Window sizes are unrelated to the claimed relationship.'],'Relevant supporting evidence directly bears on the claim and provides an observation rather than an unsupported opinion.',['Restate the claim as a relationship to be supported.','Check what each proposed addition establishes.','Select the concrete observation that supports that relationship.'],'A detail’s truth or specificity alone does not make it relevant to a particular claim.');
  if(['Irrelevant information','Sentence deletion'].includes(label))return draft('delete-off-topic-detail','numbered paragraph',`The paragraph is intended to explain “${r.title}.” Which sentence should be deleted because it does not develop that focus?\n\n${r.paragraph}`,['Sentence5','Sentence1','Sentence2','Sentence4'],['Sentence5 reports an incidental appearance detail without developing the paragraph’s focus.','Sentence1 introduces the problem or investigation.','Sentence2 supplies an observation relevant to the focus.','Sentence4 develops the practical response or qualification.'],'Delete an irrelevant sentence rather than one that introduces, supports, or resolves the paragraph’s main idea.',['Identify the stated focus.','Name what each sentence contributes.','Delete only the sentence whose contribution falls outside that focus.'],'A short sentence may still be essential, while a vivid detail can be irrelevant.');
  if(['Precision','Clarity','Sentence replacement'].includes(label))return draft('precise-meaning','notes to accurate sentence',`Which sentence most precisely reports the facts in these notes without adding an unsupported claim?\n\n${r.source}`,[r.precise,'The results proved that every possible version of the project was successful.','The project did some things with some information and got a result.','The project demonstrated that no further improvement was possible.'],['This uses specific information while preserving the limits of the notes.','The notes do not establish success for every possible version.','Vague words omit the information the notes actually provide.','The notes do not prove that improvement is impossible.'],'Precision replaces vague wording with supported specifics; it does not strengthen a claim beyond the evidence.',['Identify the facts actually established by the notes.','Replace vague labels with those facts.','Reject added universal or permanent conclusions.'],'More confident wording is not necessarily more precise.');
  if(['Concision','Redundancy','Wordiness'].includes(label))return draft('remove-repeated-meaning','meaning-preserving compression',`Which revision removes unnecessary repetition while preserving the meaning?\n\n${r.wordy}`,[r.concise,`${r.wordy} This repeats the same repeated information.`,`The project succeeded under every possible condition.`,`The project happened.`],['This keeps the finding or intended action and removes repeated wording.','This retains the original repetition and adds more.','This adds a stronger, unsupported meaning.','This deletes the essential action or finding rather than merely repetition.'],'Concision removes repeated ideas while retaining the sentence’s essential information and qualifications.',['Identify the indispensable action or finding.','Locate words that restate an idea already expressed.','Choose the revision that preserves meaning with fewer redundant words.'],'The shortest choice can be too vague or change the original meaning.');
  if(['Tone','Audience','Style'].includes(label))return draft('register-for-audience','formal factual report',`Which sentence best suits ${r.audience} while preserving the notes’ meaning?\n\nNotes: ${r.source}`,[r.precise,'The whole thing was totally awesome and obviously perfect.','Everyone involved was clueless, and the project was a complete disaster.','No reader could possibly understand these results.'],['Neutral, specific wording fits the stated audience and preserves the facts.','Informal praise exaggerates what the notes establish.','Insults and an unsupported judgment distort the facts.','This unsupported claim dismisses the audience rather than reporting the result.'],'Match register to the stated audience while keeping the content accurate and avoiding unsupported evaluative language.',['Identify the audience and purpose.','Choose neutral, specific wording for an informational or formal report.','Check that the revised tone does not change the facts.'],'Formal language should not conceal missing evidence or add exaggeration.');
  if(label==='Purpose')return draft('revision-for-purpose','purpose constrained by evidence',`The writer’s purpose is to explain what the project established and what remained uncertain. Which sentence best serves that purpose?\n\n${r.paragraph}`,[`${r.conclusion} ${r.limit}`,'The project proved that every uncertainty had been resolved.','The writer should omit all findings because some uncertainty remained.','The appearance of the materials was more interesting than the findings.'],['This states the useful finding and its remaining limit.','The paragraph preserves an uncertainty rather than resolving every question.','Uncertainty about a broader conclusion does not erase the supported finding.','This shifts away from the stated explanatory purpose.'],'A revision should serve the explicit writing purpose, including any required balance between finding and limitation.',['Identify what the stated purpose requires.','Check which findings and uncertainties the paragraph supplies.','Choose a sentence that communicates both without changing scope.'],'A qualification does not make every observed result invalid.');
  if(label==='Pronoun reference')return reference(d,c);
  throw new Error(`No authored editing plan for ${label}.`);
};
const builders:Record<string,Builder>={
  'Subject-verb agreement':agreement,'Pronoun agreement':pronounAgreement,'Pronoun case':pronounCase,'Pronoun reference':reference,
  'Verb tense':tense,'Tense consistency':tense,'Modifiers':modifiers,'Adjectives':adjectiveOnly,'Adverbs':adverbOnly,
  'Commas':commas,'Apostrophes':apostrophes,'Possessives':possessives,'Quotation marks':dialogue,'Dialogue punctuation':dialogue,
  'Capitalization':capitalization,'Standard English usage':confused,'Commonly confused words':confused,
  'Phrases':phraseOnly,'Clauses':clause,'Independent clauses':independentOnly,'Dependent clauses':dependentOnly,'Fragments':fragments,
  'Run-ons':runons,'Comma splices':commaSplices,'Sentence combining':combining,
};
for(const label of ['Main claim','Supporting details','Relevant information','Irrelevant information','Precision','Concision','Redundancy','Wordiness','Tone','Audience','Purpose','Evidence','Sentence addition','Sentence deletion','Sentence replacement','Style','Clarity'])builders[label]=revision(label);
for(const label of ['Introductions','Conclusions','Topic sentences','Sentence placement','Paragraph placement','Organization','Cohesion','Coherence','Transitions','Reordering'])builders[label]=organization(label);

// These are deliberately false, recognizable shortcuts, not random option
// fillers. The analysis/decision tasks test the rule behind an edit instead of
// repeating the direct-selection task with a different person's name.
const misconceptionRules:Record<string,[string,string,string]>={
  'Subject-verb agreement':['Make the verb agree with the closest noun, even when that noun is inside a modifier.','Every subject containing more than one noun must take a plural verb.','A participle can always replace a finite main verb without an auxiliary.'],
  'Pronoun agreement':['Choose the pronoun’s number from the nearest noun rather than its intended antecedent.','A possessive pronoun can always be replaced by an object pronoun before a noun.','Every mention of an organization requires a plural pronoun regardless of the sentence.'],
  'Pronoun case':['Always choose subject case because it sounds more formal, even after a preposition.','A reflexive pronoun can replace any ordinary object without a matching antecedent.','Choose a possessive pronoun whenever another person appears beside it.'],
  'Pronoun reference':['Retain an ambiguous pronoun because readers should choose either possible actor.','Replace the intended actor with the other person to shorten the sentence.','An unclear pronoun becomes clear simply because its sentence is grammatically complete.'],
  'Verb tense':['Use the same tense for every action, even when the time clues put the actions at different times.','Ignore words such as yesterday and tomorrow when choosing the verb form.','A later event should always be placed before an earlier event by changing the tense.'],
  'Tense consistency':['Use a present-tense verb midway through a past narrative without any change of time.','Make all verbs present even if the writer is explicitly reporting completed past events.','Treat every justified shift between an earlier and a later event as an error.'],
  'Modifiers':['Attach an opening action phrase to the nearest object, even if that object cannot perform the action.','Move a limiting word anywhere because its position cannot affect meaning.','Prefer passive wording even when it leaves the modifier’s actor unnamed or incorrect.'],
  'Adjectives':['Use an adverb before any descriptive position, even when the word describes a noun.','Combine more with an already comparative adjective to strengthen the comparison.','Treat every linking verb as an action requiring an adverb rather than a subject description.'],
  'Adverbs':['Replace the adverb with an adjective even when it must describe how an action happens.','Use a noun naming a quality wherever a description of degree is needed.','Assume that an adjective can modify another adjective without an adverbial form.'],
  'Commas':['Insert a comma wherever a speaker might pause, even between a subject and its verb.','Use only one comma to set off an interruption in the middle of a main clause.','A comma alone can join any two independent clauses.'],
  'Apostrophes':['Add an apostrophe to every ordinary plural noun.','Give possessive its an apostrophe because the noun following it belongs to something.','Place an apostrophe before the plural s even when several regular-plural owners are intended.'],
  'Possessives':['Put apostrophe+s on every owner regardless of whether the noun is a regular plural.','Use the same possessive form for one owner and several owners.','Mark each name as separately possessive even when the prompt specifies one jointly owned item.'],
  'Quotation marks':['Put a statement’s comma outside the closing quotation mark in standard American punctuation.','Treat an interrupted single quotation as two complete sentences even when its first part is dependent.','Add a comma after a quoted question mark before its speech tag.'],
  'Dialogue punctuation':['Capitalize the speech-tag verb whenever it follows a quoted question.','Omit the boundary comma between a declarative quotation and its following speech tag.','Capitalize the resumed part of one interrupted sentence as though it starts a new sentence.'],
  'Capitalization':['Capitalize ordinary verbs and common nouns whenever they seem important.','Leave names of days, languages, and places lowercase in the middle of a sentence.','Capitalize every generic job title even when it is not used as a title before a person’s name.'],
  'Standard English usage':['Interchange similar-sounding words without checking their meaning or grammatical role.','Use a past or plural verb form immediately after will instead of a base verb.','Treat nouns naming a quality as interchangeable with the verb or adjective form.'],
  'Commonly confused words':['Choose a word by its sound alone, without checking the surrounding sentence.','Replace a verb with a similarly spelled noun even when the blank requires an action.','Use lie with a direct object when the intended action is putting that object down.'],
  'Phrases':['Call a group a clause merely because it contains many words.','Treat every participle or infinitive as a finite verb with its own subject.','Assume that an introductory word alone decides whether a group contains a subject–finite-verb pair.'],
  'Clauses':['Call every group with a subject and verb independent, ignoring its subordinating word.','Treat a complete sentence as incapable of containing any dependent clauses.','Classify the sentence by its length rather than the relationships among its clauses.'],
  'Independent clauses':['Assume any subject–verb pair can stand alone even after a subordinating conjunction.','Treat an imperative as a fragment solely because its subject you is understood.','Reject a main clause as dependent merely because it contains an embedded dependent clause.'],
  'Dependent clauses':['Treat a subordinate clause as independent solely because it contains a finite verb.','Assume that a complete sentence has no dependent clauses inside it.','Call a noun phrase a dependent clause even when it has no finite predicate.'],
  'Fragments':['Add punctuation without supplying a missing main clause or finite predicate.','Make a dependent group a complete sentence simply by placing a period after it.','Replace the main verb with a participle and omit every auxiliary verb.'],
  'Run-ons':['Join complete clauses with a comma alone, regardless of the connector.','Treat however as a coordinating conjunction that licenses a comma between clauses.','Place the boundary inside a subject–verb unit instead of between the complete clauses.'],
  'Comma splices':['Assume that a comma is sufficient whenever two complete thoughts are related.','Insert however after the comma without changing the clause-boundary punctuation.','Add an extra comma inside the second clause instead of repairing the boundary.'],
  'Sentence combining':['Combine sentences by removing periods without checking clause boundaries.','Reverse the original cause and effect to make the combined sentence shorter.','Delete a stated qualification even when it changes what the source claims.'],
  'Main claim':['Choose the strongest-sounding universal claim even when the draft supports only a limited finding.','Make an incidental appearance detail the main claim because it is vivid.','Treat any uncertainty as a reason to discard every supported finding.'],
  'Supporting details':['Add an interesting fact even when it does not support the stated claim.','Replace an observed example with an unsupported prediction of universal success.','Treat any numerical or descriptive detail as support regardless of its relationship to the claim.'],
  'Relevant information':['Judge relevance by vividness rather than by contribution to the paragraph’s focus.','Keep every true detail even when it interrupts the purpose of the paragraph.','Replace a relevant observation with a personal preference on a different subject.'],
  'Irrelevant information':['Delete the central evidence because it contains more detail than the incidental sentence.','Keep an unrelated appearance detail simply because it is grammatically correct.','Delete the topic sentence rather than the detail that does not develop it.'],
  'Precision':['Turn a limited observation into a claim about all people or all conditions.','Replace specific supported facts with words such as things and stuff.','Add an unmeasured result because confident wording makes a statement precise.'],
  'Concision':['Always choose the shortest sentence even if it deletes the essential finding.','Remove a necessary qualification because fewer words are automatically better.','Retain repeated meanings to make the finding sound more important.'],
  'Redundancy':['Repeat the same idea in new synonyms because different words cannot be redundant.','Delete the unique finding while keeping phrases that say the same thing twice.','Treat all repetition as useful emphasis regardless of the writing purpose.'],
  'Wordiness':['Prefer a longer phrase even when its extra words add no meaning.','Replace a clear action with several overlapping descriptions of that action.','Make the sentence shorter by deleting the information the reader needs.'],
  'Tone':['Use exaggerated praise in a factual report even if the evidence is limited.','Use personal insults to strengthen a neutral explanation of the findings.','Change the facts whenever a more dramatic tone sounds persuasive.'],
  'Audience':['Use the same register for every audience without considering the stated purpose.','Treat a reader’s need for information as a reason to replace facts with slang praise.','Assume that a formal audience wants unsupported certainty rather than accurate qualifications.'],
  'Purpose':['Shift to an attractive incidental detail rather than serving the stated writing goal.','Omit every finding whenever the purpose also requires admitting uncertainty.','Pretend the investigation resolved every question even when the draft says otherwise.'],
  'Evidence':['Treat an unsupported belief as equivalent to an observed result.','Use a fact about the same general subject even if it does not bear on the particular claim.','Infer a universal result from one limited observation without further support.'],
  'Sentence addition':['Add the most vivid sentence even if it introduces an unrelated subject.','Insert a predicted result that the draft has not observed or established.','Add a detail that changes the claim instead of developing the stated claim.'],
  'Sentence deletion':['Delete the main evidence to shorten the paragraph, while retaining an unrelated detail.','Keep a sentence solely because it is true, even if it does not serve the paragraph’s focus.','Remove the necessary qualification so the remaining claim becomes universal.'],
  'Sentence replacement':['Replace a limited fact with a more dramatic universal claim.','Use vague wording in place of the supported details the original sentence supplies.','Change the original result because the replacement sounds smoother.'],
  'Style':['Prefer exaggerated wording over accurate language in the stated factual context.','Use insults or slang even when the audience needs a neutral informational report.','Use formal-sounding words as a substitute for evidence or clear meaning.'],
  'Clarity':['Remove the essential facts instead of clarifying their relationship.','Make an unsupported claim more certain rather than making the supported meaning more specific.','Replace a clear actor or finding with an ambiguous reference.'],
  'Introductions':['Begin with a universal conclusion the later details never establish.','Introduce an unrelated appearance detail instead of the paragraph’s actual focus.','Assume an introduction must contain every numerical detail before stating its purpose.'],
  'Conclusions':['End with a new universal claim unsupported by the developed evidence.','Close with an incidental appearance detail rather than synthesizing the findings.','Delete every qualification to make the ending sound more decisive.'],
  'Topic sentences':['Choose a sentence that names only an incidental detail instead of the shared focus.','State a claim broader than all the paragraph’s supporting details justify.','Use the first grammatically complete sentence regardless of the paragraph’s subject.'],
  'Sentence placement':['Place an interpretation before the evidence it depends on solely because it is shorter.','Separate a reference from the information needed to understand it.','Order the sentences by vocabulary difficulty rather than the development of ideas.'],
  'Paragraph placement':['Put the conclusion before introducing the issue or developing its evidence.','Put the introduction at the end regardless of the report’s development.','Place a synthesis before the examples on which that synthesis depends.'],
  'Organization':['Keep an off-topic detail as the focus and remove the central finding.','Sequence evidence and interpretation without considering what the reader needs first.','Order the draft by sentence length rather than purpose and logical relationships.'],
  'Cohesion':['Keep every pronoun or connecting phrase even when its reference is unclear.','Retain a detail that interrupts the links among the paragraph’s focused ideas.','Assume any transition will connect unrelated ideas successfully.'],
  'Coherence':['Assume grammatical sentences always form a logically understandable paragraph.','Replace the central finding with an unrelated detail without changing the stated focus.','Remove relevant support while leaving the interruption in place.'],
  'Transitions':['Choose a connector by its sound rather than the actual relationship of the two ideas.','Use a cause-and-effect connector for a qualification or contrast.','Treat addition, contrast, and consequence as interchangeable relationships.'],
  'Reordering':['Put the conclusion before its support because it sounds more important.','Place the topic after its example and interpretation regardless of what readers need.','Order the sentences by length rather than the dependencies among their ideas.'],
};
function familyNames(t:Subtopic){return [`${slug(t.label)}-direct-selection`,`${slug(t.label)}-rule-analysis`,`${slug(t.label)}-editor-decision`];}
function applicationBuilder(t:Subtopic):Builder{
  if(t.skill==='Organization')return organization(t.label,applicationRevisionContexts);
  if(t.skill==='Revision')return revision(t.label,applicationRevisionContexts);
  return builders[t.label];
}
function editingPlans(t:Subtopic,difficulty:number,contextIndex:number):Draft[]{
  const names=familyNames(t),base=builders[t.label](difficulty,contexts[contextIndex]);
  const alternate=applicationBuilder(t)(difficulty,applicationContexts[contextIndex]);
  const shortcuts=misconceptionRules[t.label];
  if(!shortcuts)throw new Error(`Missing authored misconception plan for ${t.label}.`);
  const source=base.text.split('\n\n').slice(1).join('\n\n')||base.text;
  const analysis=draft(names[1],`compare-edit-and-rule:${base.structure}`,
    `An editor is considering this ${t.label.toLowerCase()} task.\n\n${source}\n\nProposed answer or revision: “${base.choices[0]}”\n\nWhich explanation correctly justifies this proposal?`,
    [`${base.rule} ${base.reasons[0]}`,...shortcuts],
    [`The explanation identifies the relevant rule or writing goal and applies it to the proposed answer: ${base.rule}`,...shortcuts.map(shortcut=>`This proposed principle is unreliable: “${shortcut}” The actual requirement is: ${base.rule}`)] as Draft['reasons'],
    base.rule,['Identify the source’s grammatical relationship or explicit writing goal.','Explain the proposed edit using that relationship rather than a shortcut.',...base.steps],base.trap);
  const decision=draft(names[2],`choose-revision-process:${alternate.structure}`,
    `The following task concerns ${t.label.toLowerCase()} in a different writing situation.\n\n${alternate.text}\n\nDraft answers or revisions being considered:\n${alternate.choices.map((choice,i)=>`Version ${i+1}: ${choice}`).join('\n')}\n\nWhich editor’s plan would solve the task while preserving its intended meaning?`,
    [alternate.steps.join(' Then, '),...shortcuts.map(shortcut=>[alternate.steps[0],shortcut,...alternate.steps.slice(2)].join(' Then, '))] as Draft['choices'],
    [`The plan checks the necessary relationships before choosing a form or revision. ${alternate.rule}`,...shortcuts.map(shortcut=>`This shortcut would not reliably solve the stated task: “${shortcut}” ${alternate.rule}`)] as Draft['reasons'],
    alternate.rule,['Identify the task’s intended meaning before making any change.',...alternate.steps,'Check the result against the source instead of changing the facts.'],alternate.trap);
  return [{...base,family:names[0]},analysis,decision];
}
export function editingFamilies(subtopicId:string):string[]{
  const t=target(subtopicId,'editing');const builder=builders[t.label];if(!builder)return [];
  return familyNames(t);
}
export function generateEditingV3(subtopicId:string,difficulty:number,seed:number,preferredFamily?:string):ELAQuestionV3{
  level(difficulty);const t=target(subtopicId,'editing');const builder=builders[t.label];
  if(!builder)unavailable(`No authored ${t.label.toLowerCase()} editing plan is available.`);
  const contextIndex=Math.floor(seedNumber(seed)/3)%contexts.length;const plans=editingPlans(t,difficulty,contextIndex);
  const p=preferredFamily?plans.find(plan=>plan.family===preferredFamily):plans[seedNumber(seed)%plans.length];
  if(!p)unavailable(`The requested ${preferredFamily} family has no authored level ${difficulty} ${t.label.toLowerCase()} item.`);
  const rotated=ordered(p.choices,seedNumber(seed)+difficulty);const reasons=ordered(p.reasons,seedNumber(seed)+difficulty);const correct=rotated.indexOf(p.choices[0]);
  const signature=contentSignature(p.text,p.choices);
  const steps=p.steps;
  return {id:`edit-v3-${slug(t.label)}-${signature.slice(0,20)}`,subject:'ELA',skill:t.skill,difficulty,text:p.text,choices:rotated,correct,type:'mc',
    explanation:`${p.rule} The correct choice is “${p.choices[0]}.” ${p.reasons[0]}`,breakthrough:`${p.rule} Remember: ${p.trap}`,commonTrap:p.trap,distractorReasons:reasons,
    subskill:t.label,generationMethod:'finite-authored-ela-v3',estimatedTime:45+steps.length*10,domain:t.domain,topic:t.skill,subtopic:t.id,
    familyId:p.family,scenarioId:p.family.endsWith('-editor-decision')?`editing-application-${contextIndex}-${difficulty}`:`editing-authored-${contextIndex}-${difficulty}`,structureId:slug(p.structure),reasoningType:p.family.endsWith('-rule-analysis')?'compare-proposal-with-language-rule':p.family.endsWith('-editor-decision')?'evaluate-editing-process':'apply-language-rule-or-writing-purpose',misconception:p.trap,
    reasoningSteps:steps.length,solutionSteps:steps,howToThink:steps.join(' '),evidenceExplanation:p.rule,qualityVersion:ELA_QUALITY_VERSION,
    contentSignature:signature,calibration:{basis:'Authored rule and syntactic/task complexity; not statistically calibrated or human-reviewed.',status:'editorial',version:ELA_QUALITY_VERSION}};
}

export type ReadingSetOptions={count?:number;preferredFamily?:string;excludePassageIds?:string[];genre?:string;targetOnly?:boolean};
const matchesTarget=(p:Plan,t:Subtopic)=>slug(p.target)===slug(t.label);
export function readingFamilies(subtopicId:string):string[]{const t=target(subtopicId,'reading');return documents.filter(d=>d.plans.some(p=>matchesTarget(p,t))).map(d=>d.id);}
function readingQuestion(doc:Passage,plan:Plan,seed:number):ELAQuestionV3{
  const t=target(`ela-reading-${slug(plan.target)}`,'reading');
  const texts=plan.choices.map(c=>c.text);const rotated=ordered(texts,seed);const reasons=ordered(plan.choices.map(c=>c.reason),seed);
  const signature=contentSignature(plan.prompt,texts,doc.content);
  return {id:`read-v3-${doc.id}-${plan.id}`,subject:'ELA',skill:t.skill,difficulty:plan.level,text:plan.prompt,type:'mc',choices:rotated,correct:rotated.indexOf(texts[0]),
    passageId:`ela-v3-${doc.id}`,passage:{title:doc.title,content:doc.content,type:doc.genre},explanation:`The passage states, “${plan.evidence}” ${plan.interpretation} Therefore, “${texts[0]}” best answers the question.`,
    breakthrough:`${plan.steps[0]} Remember: ${plan.trap}`,commonTrap:plan.trap,distractorReasons:reasons,evidence:plan.evidence,subskill:t.label,
    generationMethod:'finite-authored-ela-v3',estimatedTime:60+plan.steps.length*15,domain:t.domain,topic:t.skill,subtopic:t.id,
    familyId:doc.id,scenarioId:doc.scenario,structureId:plan.structure,reasoningType:'textual-evidence-and-interpretation',misconception:plan.trap,reasoningSteps:plan.steps.length,
    solutionSteps:[...plan.steps,`Use the exact evidence: “${plan.evidence}”`,plan.interpretation],howToThink:plan.steps.join(' '),evidenceExplanation:plan.interpretation,
    qualityVersion:ELA_QUALITY_VERSION,contentSignature:signature,calibration:{basis:'Passage and evidence distance, inference, competing choices, and task complexity; not empirically calibrated or human-reviewed.',status:'editorial',version:ELA_QUALITY_VERSION}};
}
export function generateReadingSetV3(subtopicId:string,difficulty:number,seed:number,options:ReadingSetOptions={}):ELAQuestionV3[]{
  level(difficulty);const t=target(subtopicId,'reading');const count=options.count??4;
  if(!Number.isInteger(count)||count<1||count>4)throw new Error('A reading set must contain 1 to 4 questions.');
  const available=documents.filter(doc=>(!options.genre||doc.genre.toLowerCase()===options.genre.toLowerCase())&&
    (!options.preferredFamily||doc.id===options.preferredFamily)&&!(options.excludePassageIds||[]).includes(`ela-v3-${doc.id}`)&&
    doc.plans.some(p=>p.level===difficulty&&matchesTarget(p,t))&&doc.plans.filter(p=>p.level===difficulty&&(!options.targetOnly||matchesTarget(p,t))).length>=count);
  if(!available.length)unavailable(`No unused authored ${t.label.toLowerCase()} passage set at level ${difficulty} matches this request.`);
  const doc=available[seedNumber(seed)%available.length];const plans=doc.plans.filter(p=>p.level===difficulty);
  const requested=ordered(plans.filter(p=>matchesTarget(p,t)),seed)[0];
  const others=ordered(plans.filter(p=>p.id!==requested.id&&(!options.targetOnly||matchesTarget(p,t))),seedNumber(seed)+1).slice(0,count-1);
  return [requested,...others].map((p,i)=>readingQuestion(doc,p,seedNumber(seed)+i));
}
/** Used to inspect/seed the actual finite corpus, never a claim of unlimited items. */
export function allReadingQuestionsV3():ELAQuestionV3[]{return documents.flatMap((d,di)=>d.plans.map((p,pi)=>readingQuestion(d,p,di+pi)));}
export function elaV3Coverage(){
  const readingAvailability=SUBTOPICS.filter(topic=>topic.kind==='reading').flatMap(topic=>Array.from({length:5},(_,i)=>{
    const difficulty=i+1,eligible=documents.filter(doc=>doc.plans.some(plan=>matchesTarget(plan,topic)&&plan.level===difficulty));
    return{subtopic:topic.id,difficulty,passages:eligible.length,questions:eligible.reduce((sum,doc)=>sum+doc.plans.filter(plan=>matchesTarget(plan,topic)&&plan.level===difficulty).length,0)};
  }));
  return {version:ELA_QUALITY_VERSION,passages:documents.length,readingQuestions:documents.reduce((n,d)=>n+d.plans.length,0),
    reading:documents.flatMap(d=>d.plans.map(p=>({passageId:`ela-v3-${d.id}`,subtopic:`ela-reading-${slug(p.target)}`,difficulty:p.level,familyId:d.id}))),
    readingAvailability,unsupportedReadingCombinations:readingAvailability.filter(item=>item.passages===0).map(({subtopic,difficulty})=>({subtopic,difficulty})),
    editing:SUBTOPICS.filter(topic=>topic.kind==='editing').map(topic=>({subtopic:topic.id,taskFamilies:editingFamilies(topic.id),levels:[1,2,3,4,5]})),
    passageLevels:Array.from({length:5},(_,i)=>({difficulty:i+1,passages:documents.filter(doc=>doc.plans.some(plan=>plan.level===i+1)).length})),
    editorialReview:'authored-and-automatically-validated; not independently human-reviewed',
    limitation:'Finite authored plans. Changing a seed, choice order, name, or difficulty label is not a new reading passage.'};
}
